package tesoreria.compras.ordencompra.application.usecases;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import tesoreria.compras.ordencompra.domain.exception.OrdenCompraNotFoundException; import tesoreria.compras.ordencompra.domain.model.*; import tesoreria.compras.ordencompra.domain.ports.in.UpdateOrdenCompraUseCase; import tesoreria.compras.ordencompra.domain.ports.out.OrdenCompraRepository; import java.time.LocalDate; import java.util.List;
@Component @RequiredArgsConstructor public class UpdateOrdenCompraUseCaseImpl implements UpdateOrdenCompraUseCase { private final OrdenCompraRepository repository; @Transactional public OrdenCompra update(Long id,LocalDate f,Integer p,Integer s,String o,List<OrdenCompraItem> i){var orden=repository.findByIdForUpdate(id).orElseThrow(()->new OrdenCompraNotFoundException(id));return repository.save(orden.actualizar(f,p,s,o,i));} }
